function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 50000)) return 'Each value is an integer from 1 to 50000.';
  const total = nums.length * (nums.length + 1) / 2;
  if (!Number.isInteger(k) || k < 1 || k > total) return 'k must be between 1 and the number of subarrays, n * (n + 1) / 2.';
  return null;
}

