function kthSmallestSubarraySum(nums, k) {
  let low = Math.min(...nums);
  let high = nums.reduce((total, num) => total + num, 0);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let count = 0;
    let windowSum = 0;
    let left = 0;
    for (let right = 0; right < nums.length; right++) {
      windowSum += nums[right];
      while (windowSum > mid) {
        windowSum -= nums[left];
        left++;
      }
      count += right - left + 1;
    }
    if (count >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

