function kthSmallestSubarraySum(nums, k) {
  // List every subarray sum, sort them, and read off position k.
  const sums = [];
  for (let i = 0; i < nums.length; i++) {
    let total = 0;
    for (let j = i; j < nums.length; j++) {
      total += nums[j];
      sums.push(total);
    }
  }
  sums.sort((a, b) => a - b);
  return sums[k - 1];
}

