function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const roll = rand();
  const top = roll < 0.4 ? 5 : roll < 0.7 ? 100 : 50000;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const total = n * (n + 1) / 2;
  const choice = rand();
  const k = choice < 0.1 ? 1 : choice < 0.2 ? total : 1 + Math.floor(rand() * total);
  return [nums, k];
}
